// до C# 4: Enter перед try
Monitor.Enter(_gate);
// ← сюда могло прилететь ThreadAbortException:
//   замок взят, а finally его не охраняет
try     { /* тело lock */ }
finally { Monitor.Exit(_gate); }

// с C# 4: Enter внутри try
bool lockTaken = false;
try
{
    // lockTaken = true ровно в момент захвата
    Monitor.Enter(_gate, ref lockTaken);
    // тело lock
}
finally
{
    if (lockTaken) Monitor.Exit(_gate);
}

